begin;
insert into auth.users(id,email) values('ffffffff-ffff-4fff-8fff-fffffffffff1','allowlist@example.com');
do $$ declare actor uuid:='ffffffff-ffff-4fff-8fff-fffffffffff1';g uuid;r jsonb;copy jsonb;account uuid:=gen_random_uuid();key uuid:=gen_random_uuid();before_balance numeric;begin
 r:=public.s2a_group_create('Model policy',actor,'openai',1,'{"model_allowlist":{"enabled":true,"models":[" GPT-4.1 ","gpt-4.1","gpt-5.5-*","literal_%*"]}}');g:=(r->>'id')::uuid;
 if r->'model_allowlist'<>'{"enabled":true,"models":["GPT-4.1","gpt-5.5-*","literal_%*"]}' then raise exception 'policy normalization failed %',r;end if;
 if not public.s2a_model_allowlist_allows(r->'model_allowlist',array['gpt-4.1']) or not public.s2a_model_allowlist_allows(r->'model_allowlist',array['gpt-5.5-mini']) then raise exception 'matching policy rejected';end if;
 if public.s2a_model_allowlist_allows(r->'model_allowlist',array['literalXYZ']) or not public.s2a_model_allowlist_allows(r->'model_allowlist',array['literal_%exact']) then raise exception 'wildcard treated SQL metacharacters as patterns';end if;
 insert into public.s2a_accounts(id,group_id,name,account_fingerprint,ciphertext,iv) values(account,g,'Model policy account','allowlist-account','cipher','iv');
 insert into public.s2a_keys(id,user_id,group_id,name,key_hash,key_prefix) values(key,actor,g,'Restricted',repeat('7',64),'prefix');
 perform public.s2a_wallet_update(actor,10,'set');select balance into before_balance from public.s2a_wallets where user_id=actor;
 r:=public.s2a_acquire(repeat('7',64),'unpriced-denied-model',gen_random_uuid(),'{}',true,null,'{}');
 if r->>'error'<>'model_not_allowed' or r->>'status'<>'403' then raise exception 'denied model reached pricing %',r;end if;
 if exists(select 1 from public.s2a_leases where key_id=key) or exists(select 1 from public.s2a_usage where key_id=key) or (select window_count from public.s2a_keys where id=key)<>0 or (select balance from public.s2a_wallets where user_id=actor)<>before_balance then raise exception 'denied request consumed resources';end if;
 r:=public.s2a_acquire(repeat('7',64),'__models__',gen_random_uuid(),'{}',true,null,'{"policy_model":"blocked","model_candidates":["blocked"]}');if r->>'status'<>'404' or r->>'error'<>'model_not_found' then raise exception 'single catalog policy bypassed %',r;end if;
 r:=public.s2a_acquire(repeat('7',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{"policy_model":"other","model_candidates":[]}');if r->>'status'<>'400' then raise exception 'inconsistent trusted model context accepted';end if;
 r:=public.s2a_acquire(repeat('7',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{"model_candidates":"wrong"}');if r->>'status'<>'400' then raise exception 'invalid aliases accepted';end if;
 r:=public.s2a_acquire(repeat('7',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{"policy_model":"gpt-4.1","model_candidates":["gpt-4.1"]}');
 if not r ? 'lease_id' or r->'model_allowlist' is distinct from (select model_allowlist from public.s2a_groups where id=g) then raise exception 'allowed request or catalog snapshot failed %',r;end if;
 perform public.s2a_finish((r->>'lease_id')::uuid,200,'incomplete');
 copy:=public.s2a_group_duplicate(g,actor,'allowlist-copy');if copy->'group'->'model_allowlist' is distinct from r->'model_allowlist' then raise exception 'copy lost policy';end if;
 if not exists(select 1 from jsonb_array_elements(public.s2a_groups_available(actor)) x where x->>'id'=g::text and x->'model_allowlist'=r->'model_allowlist') then raise exception 'available group lost policy';end if;
 begin update public.s2a_groups set model_allowlist='{"enabled":true,"models":[]}' where id=g;raise exception 'empty enabled policy accepted';exception when raise_exception then if sqlerrm<>'invalid_model_allowlist' then raise;end if;end;
 begin update public.s2a_groups set model_allowlist='{"enabled":false,"models":["bad*middle"]}' where id=g;raise exception 'invalid wildcard accepted';exception when raise_exception then if sqlerrm<>'invalid_model_allowlist' then raise;end if;end;
 update public.s2a_groups set model_allowlist='{"enabled":false,"models":[]}' where id=g;
 r:=public.s2a_acquire(repeat('7',64),'__models__',gen_random_uuid(),'{}',true,null,'{"policy_model":"blocked","model_candidates":["blocked"]}');if not r ? 'lease_id' then raise exception 'disabled policy still denies %',r;end if;
 perform public.s2a_finish((r->>'lease_id')::uuid,200,'completed');
 if has_function_privilege('authenticated','public.s2a_model_allowlist_allows(jsonb,text[])','execute') or has_function_privilege('anon','public.s2a_model_allowlist_normalize(jsonb)','execute') then raise exception 'policy helpers exposed';end if;
end $$;
rollback;
